#include <benchmark/benchmark.h>

// 1. PROFILE: perf record ./bench && perf report --sort symbol
//    Also ask the compiler what it did: -fopt-info-vec -fopt-info-inline
//    (it tells you which loops vectorised and which calls inlined - often the
//    answer is 'the compiler already inlined it' or 'it did NOT vectorise it')

struct Row { double a, b, c; };

// 3. ONE CHANGE, at the measured hotspot. The usual C++ wins:
//  SoA instead of AoS, so a hot field streams:
static double sum_b(const std::vector<Row>& rows) {
    double s = 0;
    for (const auto& r : rows) s += r.b;   // contiguous; the loop vectorises
    return s;
}
//  reserve, so the hot vector does not reallocate:
//    rows.reserve(expected);
//  [[gnu::always_inline]] on the one measured hot small function.

BENCHMARK(SumB)->Range(1 << 10, 1 << 22);
BENCHMARK_MAIN();
/* 4. VERIFY with Google Benchmark: it reports a variance and a confidence
 *    interval, so you can see whether a 3% 'win' is inside the noise.
 * 5. GUARD: run the benchmark in CI with a threshold. */
